(() => {
  const state = {messages:[],draft:'',pending:null,busy:false,stage:'start',review:null,choices:[],source:null,followup:null,progress:'',controller:null,model:'',wallet:null,turn:null};
  // Model choice and credits: every question costs the chosen model's credits (120 = 8 Gemini 3 Flash or 15 GPT-5 nano).
  const FALLBACK_MODELS=[{id:'gemini-3-flash',label:'Gemini 3 Flash',note:'Most accurate',credits:15},{id:'gpt-5-nano',label:'GPT-5 nano',note:'More searches',credits:8}];
  const models = () => state.wallet?.models?.length?state.wallet.models:FALLBACK_MODELS;
  const currentModel = () => models().find(m=>m.id===state.model)||models().find(m=>m.id===state.wallet?.defaultModel)||models()[0];
  try{state.model=localStorage.getItem('tbw-discover-model')||'';}catch{}
  let walletRequested=false;
  async function loadWallet(){if(walletRequested||typeof window.fetch!=='function')return;walletRequested=true;try{const r=await window.fetch('/api/discover/credits');if(r.ok){state.wallet=await r.json();paint();}}catch{}}
  const searchesLeft = model => state.wallet?Math.floor(state.wallet.remaining/model.credits):null;
  const renderWallet = () => {if(!state.wallet)return '';const m=currentModel(),left=searchesLeft(m);return `<span class="dc-wallet ${state.wallet.remaining<m.credits?'empty':''}" title="Each question costs ${m.credits} credits with ${escape(m.label)}"><b>${state.wallet.remaining}</b> credits · ${left} ${left===1?'search':'searches'} left</span>`;};
  const escape = value => String(value ?? '').replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
  const root = () => document.getElementById('discover-conversation');
  const examples = [
    'Find a relaxed brown blazer under ₹4,000',
    'Show me a similar outfit from this screenshot',
    'Where can I find a dress like the one at Cannes?'
  ];
  const renderMessage = message => `<article class="dc-message ${message.role==='user'?'dc-user':'dc-assistant'}"><span class="dc-speaker">${message.role==='user'?'You':'The Better Wardrobe'}</span><div class="dc-bubble">${message.image?`<img src="${escape(message.image)}" alt="Uploaded fashion reference" class="dc-message-image">`:''}${message.text?`<p>${escape(message.text)}</p>`:''}${message.meta?`<small class="dc-meta">${escape(message.meta)}</small>`:''}</div></article>`;
  const renderChoices = () => state.stage!=='choose'?'':`<div class="dc-choice-panel"><p>Which piece should I look for?</p><div class="dc-choice-list">${state.choices.map((item,index)=>`<button type="button" data-conversation="choice" data-index="${index}">${escape(item.label)} <span aria-hidden="true">↗</span></button>`).join('')}</div></div>`;
  // Model non-answers ("unknown") show as an empty field with its placeholder, not as a value to search.
  const known = value => /^(unknown|n\/?a|none|not visible|unclear)$/i.test(String(value??'').trim())?'':value;
  const field = (label,name,value,placeholder='') => `<label><span>${label}</span><input name="${name}" value="${escape(known(value))}" placeholder="${escape(placeholder)}"></label>`;
  const renderReview = () => {
    if(state.stage!=='review'||!state.review?.attributes)return '';
    const {attributes:a,query,budget,uncertainty}=state.review;
    return `<form id="dc-review" class="dc-review"><div class="dc-review-heading"><span class="dc-kicker">Before I search</span><h3>Is this the right piece?</h3><p>Change any detail that looks off. I’ll use these terms to look for products.</p></div><div class="dc-review-grid">${field('Item','category',a.category,'e.g. blazer')}${field('Colour','colour',a.colour,'Any colour')}${field('Fit','fit',a.fit,'Any fit')}${field('Detail','details',a.details,'Collar, fabric, print…')}${field('Search phrase','query',query,'What should I search for?')}${field('Budget in ₹','budget',budget??'','Optional')}</div>${uncertainty?`<p class="dc-uncertainty">Worth checking: ${escape(uncertainty)}</p>`:''}<div class="dc-review-actions"><button type="submit" class="dc-main-button">Find matches <span aria-hidden="true">→</span></button><span>Product links open at the retailer. Prices and stock may change.</span></div></form>`;
  };
  const renderRetrieval = () => {
    const t=state.results?.trace;if(!t)return '';
    const a=state.review?.attributes||{},budget=state.review?.budget;
    const facts=[a.category,a.colour,a.fit,a.pattern,a.details,budget?`under ₹${Number(budget).toLocaleString('en-IN')}`:''].filter(v=>v&&v!=='unknown');
    // Trace entries read "phrase · route"; show each phrase once with the routes it went to.
    const routes=new Map();for(const entry of t.queries||[]){const [phrase,route]=String(entry).split(' · ');if(!routes.has(phrase))routes.set(phrase,[]);if(route)routes.get(phrase).push(route);}
    const queries=[...routes].slice(0,4),removed=(t.titleRejected||0)+(t.domesticRejected||0),shown=Math.min(state.results.results?.length||0,6);
    const seconds=t.elapsedMs?` · ${(t.elapsedMs/1000).toFixed(1)}s`:'';
    const step=(n,title,body)=>`<li><span class="dc-step-n">${n}</span><div><strong>${title}</strong>${body}</div></li>`;
    const routeCount=(t.queries||[]).length;
    return `<details class="dc-retrieval" open><summary>How I searched · ${routeCount} ${routeCount===1?'search':'searches'}${seconds}</summary><ol>${
      step(1,'Understood',`<div class="dc-chips">${facts.map(f=>`<span>${escape(f)}</span>`).join('')}</div>`)}${
      step(2,'Searched',`<div class="dc-queries">${queries.map(([q,via])=>`<span class="dc-query"><code>${escape(q)}</code>${via.length?`<small>${escape(via.join(' · '))}</small>`:''}</span>`).join('')}</div>`)}${
      step(3,'Narrowed down',`<p>${t.retrieved||0} found${removed?` · ${removed} off-topic or outside India removed`:''}${t.visuallyAssessed?` · ${t.visuallyAssessed} compared against your piece`:''} · <b>${shown} shown</b></p>${t.providerFailures?.length?`<p class="dc-result-note">${t.providerFailures.length} source${t.providerFailures.length===1?' was':'s were'} slow and skipped.</p>`:''}`)}</ol></details>`;
  };
  const renderResults = () => {
    if(state.stage!=='results'||!state.results)return '';
    const {results=[],warnings=[]}=state.results;
    return `<section class="dc-results" aria-label="Shopping results"><div class="dc-results-head"><span class="dc-kicker">Search results</span><h3>${results.length?'A few places to start':'No confident product links yet'}</h3><p>${results.length?'Compare the item on the retailer’s site before buying.':'Try adding a colour, garment type, or a clearer crop.'}</p></div>${renderRetrieval()}${results.length?`<div class="dc-result-grid">${results.slice(0,6).map(item=>`<a class="dc-result" href="${escape(item.url)}" target="_blank" rel="noopener noreferrer"><div class="dc-result-image">${item.image?`<img src="${escape(item.image)}" alt="${escape(item.title)}" loading="lazy">`:'<span>View at retailer</span>'}</div><div class="dc-result-copy"><small>${escape(item.merchant||'Retailer')} ${item.market==='global'?'· Global':''}</small><strong>${escape(item.title)}</strong><span>${escape(item.priceText||'Check price at retailer')} ↗</span></div></a>`).join('')}</div>`:''}${warnings.length?`<p class="dc-result-note">${escape(warnings[0])}</p>`:''}<p class="dc-result-note">Search suggestions, not verified exact matches. Confirm size, delivery and availability with the store.</p></section>`;
  };
  function content(){return `<section id="discover-conversation" class="dc-shell"><div class="dc-intro"><div><span class="dc-kicker">Discover / search</span><h1>Tell me what you’re looking for.</h1><p>Describe a piece, add a screenshot, or use both. We’ll narrow it down together.</p></div><button type="button" class="dc-reset" data-conversation="reset" ${state.messages.length?'':'hidden'}>New search ↗</button></div><div class="dc-panel"><div class="dc-thread" aria-live="polite">${state.messages.length?state.messages.map(renderMessage).join(''):`<div class="dc-welcome"><span class="dc-spark" aria-hidden="true">✳</span><h2>What caught your eye?</h2><p>A photo, a specific piece, even half a thought. Start anywhere.</p></div><div class="dc-examples">${examples.map((x,i)=>`<button type="button" data-conversation="example" data-index="${i}">${escape(x)} <span aria-hidden="true">↗</span></button>`).join('')}</div>`}${renderChoices()}${renderReview()}${renderResults()}${state.busy?`<div class="dc-thinking" role="status"><span class="dc-thinking-dot" aria-hidden="true"></span>${escape(state.progress||'Looking at your request…')} <button type="button" data-conversation="cancel">Cancel</button></div>`:''}</div><form id="dc-compose" class="dc-composer"><input id="dc-image-input" type="file" accept="image/jpeg,image/png,image/webp" hidden><div class="dc-attachment">${state.pending?`<div class="dc-pending"><img src="${escape(state.pending)}" alt="Screenshot ready to send"><span>Screenshot attached</span><button type="button" data-conversation="remove-image" aria-label="Remove screenshot">×</button></div>`:''}</div><div class="dc-compose-row"><button type="button" class="dc-attach" data-conversation="attach" aria-label="Attach a screenshot" title="Attach screenshot">＋</button><label class="dc-text-wrap"><span class="sr-only">Describe what you are looking for</span><textarea id="dc-text" rows="2" maxlength="500" placeholder="Describe it, ask a question, or add a screenshot…" ${state.busy?'disabled':''}>${escape(state.draft)}</textarea></label></div><div class="dc-compose-bar"><label class="dc-model"><span class="sr-only">Model</span><select id="dc-model" ${state.busy?'disabled':''}>${models().map(m=>`<option value="${escape(m.id)}" ${m.id===currentModel().id?'selected':''}>${escape(m.label)} · ${m.credits} credits</option>`).join('')}</select></label>${renderWallet()}<button type="submit" class="dc-send" ${state.busy||(state.wallet&&state.wallet.remaining<currentModel().credits)?'disabled':''}>Search <span aria-hidden="true">→</span></button></div><p class="dc-compose-help">${escape(currentModel().note)} · JPG, PNG or WebP · Your image is sent for analysis only when you press search.</p></form></div><div class="dc-below"><span>01 / Search by conversation</span><span>Keep exploring the mall and community below ↓</span></div></section>`;}
  function paint(focus=false){const target=root();if(!target)return;target.outerHTML=content();const thread=document.querySelector?.('.dc-thread');if(thread)thread.scrollTop=thread.scrollHeight;if(focus)document.getElementById('dc-text')?.focus();}
  async function request(action,body,signal){const response=await fetch(`/api/discover/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...body,model:currentModel().id,...(action==='search'&&state.turn?{turn:state.turn}:{})}),signal});let data;try{data=await response.json();}catch{throw new Error('The search service did not respond. Please retry.');}if(!response.ok)throw Object.assign(new Error(data.error||'Could not complete this search.'),{status:response.status});if(data.turn)state.turn=data.turn;if(data.credits&&state.wallet)state.wallet={...state.wallet,remaining:data.credits.remaining};return data;}
  async function toImage(file){if(!file||!['image/jpeg','image/png','image/webp'].includes(file.type))throw new Error('Choose a JPG, PNG or WebP screenshot.');if(file.size>10*1024*1024)throw new Error('Choose an image under 10 MB.');const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,1280/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);let quality=.86,data=canvas.toDataURL('image/jpeg',quality);while(data.length>3_700_000&&quality>.45){quality-=.12;data=canvas.toDataURL('image/jpeg',quality);}if(data.length>4_100_000)throw new Error('This image is still too large. Try a tighter crop.');return data;}finally{bitmap.close();}}
  async function cropImage(src,crop){const bitmap=await createImageBitmap(await (await fetch(src)).blob());try{const x=Math.max(0,Math.round(bitmap.width*crop.left/100)),y=Math.max(0,Math.round(bitmap.height*crop.top/100));const w=Math.max(1,Math.min(bitmap.width-x,Math.round(bitmap.width*crop.width/100))),h=Math.max(1,Math.min(bitmap.height-y,Math.round(bitmap.height*crop.height/100)));const canvas=document.createElement('canvas');canvas.width=w;canvas.height=h;canvas.getContext('2d').drawImage(bitmap,x,y,w,h,0,0,w,h);return canvas.toDataURL('image/jpeg',.84);}finally{bitmap.close();}}
  async function interpret(text,image,target='',previous=null){
    state.controller=new AbortController();state.busy=true;state.progress='Understanding the piece…';paint();
    try{const data=await request('interpret',{text,image,target,previous},state.controller.signal);const meta=data.credits?`${currentModel().label} · ${data.credits.cost} credits · ${data.credits.remaining} left`:'';if(data.question||!data.attributes){state.stage='clarify';state.followup={text,image,previous};state.messages.push({role:'assistant',meta,text:data.question||'What kind of item should I look for?'});}else{state.review=data;state.stage='review';state.followup=null;state.messages.push({role:'assistant',meta,text:`I’ll look for ${[data.attributes.colour,data.attributes.fit,data.attributes.category].filter(Boolean).join(' ')}. Check the details below before I search.`});}}
    catch(error){if(error.name!=='AbortError')state.messages.push({role:'assistant',text:error.message||'I could not read that. Please try again.'});}
    finally{state.busy=false;state.controller=null;state.progress='';paint();}
  }
  async function send(){if(state.busy)return;const text=state.draft.trim(),image=state.pending;if(!text&&!image)return;state.draft='';state.pending=null;state.messages.push({role:'user',text,image});const clarification=state.followup,previous=state.review||clarification?.previous||null;state.followup=null;const searchText=clarification?[clarification.text,text].filter(Boolean).join('. '):text;const searchImage=image||clarification?.image||null;state.source={text:searchText,image:searchImage};state.review=null;state.results=null;state.stage='working';state.busy=true;state.controller=new AbortController();state.progress='Reading the screenshot…';paint();
    if(searchImage&&!searchText){try{const detected=await request('detect',{image:searchImage},state.controller.signal);if(detected.items?.length>1){state.choices=detected.items;state.stage='choose';state.busy=false;state.controller=null;state.messages.push({role:'assistant',text:'I can see a few pieces. Which one should I search for?'});paint();return;}if(detected.items?.length===1){const crop=await cropImage(searchImage,detected.items[0].crop);state.source.image=crop;await interpret('',crop,detected.items[0].label);return;}}catch(error){if(error.name==='AbortError'){state.busy=false;state.controller=null;return;}}}
    await interpret(searchText,searchImage,'',previous);
  }
  async function search(form){if(state.busy||!state.review?.attributes)return;const data=new FormData(form);const category=String(data.get('category')||'').trim(),query=String(data.get('query')||'').trim(),budget=String(data.get('budget')||'').trim();if(!category){state.messages.push({role:'assistant',text:'Tell me what kind of item it is first.'});paint();return;}state.review.attributes={...state.review.attributes,category,colour:String(data.get('colour')||'').trim(),fit:String(data.get('fit')||'').trim(),details:String(data.get('details')||'').trim()};state.review.query=query;state.review.budget=budget?Number(budget):null;state.stage='searching';state.busy=true;state.progress='Looking across stores…';state.controller=new AbortController();paint();try{state.results=await request('search',{attributes:state.review.attributes,query,budget:state.review.budget,market:'in',image:state.source?.image||undefined},state.controller.signal);state.stage='results';state.messages.push({role:'assistant',text:state.results.results?.length?'Here are some leads. Open each retailer to check the details.':'I couldn’t find a confident product link this time. Try a clearer image or different details.'});}catch(error){if(error.name!=='AbortError'){state.stage='review';state.messages.push({role:'assistant',text:error.message||'The product search did not finish. You can retry below.'});}}finally{state.busy=false;state.controller=null;state.progress='';paint();}}
  document.addEventListener('click',async event=>{const button=event.target.closest('[data-conversation]');if(!button)return;const action=button.dataset.conversation;if(action==='attach'){document.getElementById('dc-image-input')?.click();}else if(action==='remove-image'){state.pending=null;paint(true);}else if(action==='example'){state.draft=examples[Number(button.dataset.index)]||'';paint(true);}else if(action==='reset'){state.controller?.abort();Object.assign(state,{messages:[],draft:'',pending:null,busy:false,stage:'start',review:null,choices:[],source:null,followup:null,progress:'',controller:null,results:null});paint(true);}else if(action==='cancel'){state.controller?.abort();state.busy=false;state.stage=state.review?'review':'start';state.progress='';paint();}else if(action==='choice'){const item=state.choices[Number(button.dataset.index)];if(!item||!state.source?.image)return;state.choices=[];try{const crop=await cropImage(state.source.image,item.crop);state.source.image=crop;await interpret(state.source.text||'',crop,item.label);}catch{state.messages.push({role:'assistant',text:'That crop could not be read. Please attach the image again.'});state.stage='start';paint();}}});
  document.addEventListener('change',async event=>{if(event.target.id!=='dc-image-input')return;const file=event.target.files?.[0];if(!file)return;try{state.pending=await toImage(file);paint(true);}catch(error){state.messages.push({role:'assistant',text:error.message});paint();}});
  document.addEventListener('input',event=>{if(event.target.id==='dc-text')state.draft=event.target.value;});
  document.addEventListener('change',event=>{if(event.target.id!=='dc-model')return;state.model=event.target.value;try{localStorage.setItem('tbw-discover-model',state.model);}catch{}paint();});
  document.addEventListener('submit',event=>{if(event.target.id==='dc-compose'){event.preventDefault();send();}else if(event.target.id==='dc-review'){event.preventDefault();search(event.target);}});
  document.addEventListener('keydown',event=>{if(event.target.id==='dc-text'&&event.key==='Enter'&&(event.ctrlKey||event.metaKey)){event.preventDefault();send();}});
  window.DiscoverConversation={render:()=>{loadWallet();return content();}};
})();
